#include <zephyr/ztest.h>
#include <zephyr/kernel.h>
#include <zephyr/sys/atomic.h>
#include <zephyr/sys/k_heap.h>

#define MSG_SIZE 4
#define MSGQ_LEN 2

K_MSGQ_DEFINE(kmsgq, MSG_SIZE, MSGQ_LEN, 4);

static char msg_buf[MSG_SIZE];

/* Helper to fill the message queue */
static void fill_msgq(struct k_msgq *msgq)
{
    for (int i = 0; i < MSGQ_LEN; i++) {
        zassert_ok(k_msgq_put(msgq, msg_buf, K_NO_WAIT), "Failed to put message");
    }
}

/* Helper to empty the message queue */
static void empty_msgq(struct k_msgq *msgq)
{
    while (k_msgq_get(msgq, msg_buf, K_NO_WAIT) == 0) {
        /* continue emptying */
    }
}

/* Test case for message queue alloc (dynamic allocation) */
static void test_msgq_alloc(void)
{
    struct k_msgq *dyn_msgq;
    char *dyn_msgq_buffer;
    int ret;

    dyn_msgq_buffer = k_malloc(K_MSGQ_DEFINE_FOR_K_MSGQ_ALLOC(MSG_SIZE, MSGQ_LEN));
    zassert_not_null(dyn_msgq_buffer, "Failed to allocate buffer for dynamic msgq");

    dyn_msgq = k_msgq_alloc(dyn_msgq_buffer, MSG_SIZE, MSGQ_LEN);
    zassert_not_null(dyn_msgq, "Failed to allocate dynamic msgq");

    ret = k_msgq_put(dyn_msgq, msg_buf, K_NO_WAIT);
    zassert_ok(ret, "Failed to put message to dynamic msgq");

    ret = k_msgq_get(dyn_msgq, msg_buf, K_NO_WAIT);
    zassert_ok(ret, "Failed to get message from dynamic msgq");

    k_msgq_free(dyn_msgq);
    k_free(dyn_msgq_buffer);
}

/* Test case for message queue attributes get */
static void test_msgq_attrs_get(void)
{
    struct k_msgq_attrs attrs;

    k_msgq_get_attrs(&kmsgq, &attrs);

    zassert_equal(attrs.msg_size, MSG_SIZE, "Incorrect message size");
    zassert_equal(attrs.max_msgs, MSGQ_LEN, "Incorrect max messages");
    zassert_equal(attrs.used_msgs, 0, "Incorrect used messages (should be 0 initially)");

    fill_msgq(&kmsgq);
    k_msgq_get_attrs(&kmsgq, &attrs);
    zassert_equal(attrs.used_msgs, MSGQ_LEN, "Incorrect used messages (should be full)");

    empty_msgq(&kmsgq);
    k_msgq_get_attrs(&kmsgq, &attrs);
    zassert_equal(attrs.used_msgs, 0, "Incorrect used messages (should be empty)");
}

/* Test case for message queue ISR context */
static K_THREAD_STACK_DEFINE(isr_thread_stack, 512);
static struct k_thread isr_thread_data;
static struct k_msgq isr_msgq;
static char isr_msg_buffer[MSG_SIZE * MSGQ_LEN];

static void isr_thread_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    int ret;
    char rx_msg[MSG_SIZE];

    /* Try to get from empty queue in thread context */
    ret = k_msgq_get(&isr_msgq, rx_msg, K_NO_WAIT);
    zassert_equal(ret, -ENOMSG, "Expected -ENOMSG from empty queue in thread");

    /* Put a message from thread context */
    ret = k_msgq_put(&isr_msgq, msg_buf, K_NO_WAIT);
    zassert_ok(ret, "Failed to put message from thread");

    /* Get the message back */
    ret = k_msgq_get(&isr_msgq, rx_msg, K_NO_WAIT);
    zassert_ok(ret, "Failed to get message from thread");
}

static void isr_handler(const void *arg)
{
    ARG_UNUSED(arg);
    int ret;
    char rx_msg[MSG_SIZE];

    /* Try to put to full queue in ISR context */
    fill_msgq(&isr_msgq); /* Fill it first */
    ret = k_msgq_put(&isr_msgq, msg_buf, K_NO_WAIT);
    zassert_equal(ret, -ENOMSG, "Expected -ENOMSG from full queue in ISR");
    empty_msgq(&isr_msgq); /* Empty for next test */

    /* Put a message from ISR context */
    ret = k_msgq_put(&isr_msgq, msg_buf, K_NO_WAIT);
    zassert_ok(ret, "Failed to put message from ISR");

    /* Get the message back from ISR context */
    ret = k_msgq_get(&isr_msgq, rx_msg, K_NO_WAIT);
    zassert_ok(ret, "Failed to get message from ISR");
}

static void test_msgq_isr(void)
{
    k_msgq_init(&isr_msgq, isr_msg_buffer, MSG_SIZE, MSGQ_LEN);

    k_thread_create(&isr_thread_data, isr_thread_stack,
                    K_THREAD_STACK_SIZEOF(isr_thread_stack),
                    isr_thread_entry, NULL, NULL, NULL,
                    K_PRIO_PREEMPT(0), 0, K_NO_WAIT);

    /* Simulate an ISR call */
    isr_handler(NULL);

    k_thread_join(&isr_thread_data, K_FOREVER);
}

/* Test case for message queue thread overflow (blocking put/get) */
#define OVERFLOW_MSGQ_LEN 1
K_MSGQ_DEFINE(overflow_msgq, MSG_SIZE, OVERFLOW_MSGQ_LEN, 4);

static K_THREAD_STACK_DEFINE(overflow_thread_stack, 512);
static struct k_thread overflow_thread_data;

static void overflow_thread_entry(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    int ret;
    char rx_msg[MSG_SIZE];

    /* This thread will block trying to put a message into a full queue */
    ret = k_msgq_put(&overflow_msgq, msg_buf, K_FOREVER);
    zassert_ok(ret, "Overflow thread failed to put message");

    /* This thread will block trying to get a message from an empty queue */
    ret = k_msgq_get(&overflow_msgq, rx_msg, K_FOREVER);
    zassert_ok(ret, "Overflow thread failed to get message");
}

static void test_msgq_thread_overflow(void)
{
    int ret;
    char rx_msg[MSG_SIZE];

    empty_msgq(&overflow_msgq); /* Ensure empty */

    /* Put one message to fill the queue */
    ret = k_msgq_put(&overflow_msgq, msg_buf, K_NO_WAIT);
    zassert_ok(ret, "Failed to put initial message");

    k_thread_create(&overflow_thread_data, overflow_thread_stack,
                    K_THREAD_STACK_SIZEOF(overflow_thread_stack),
                    overflow_thread_entry, NULL, NULL, NULL,
                    K_PRIO_PREEMPT(0), 0, K_NO_WAIT);

    k_sleep(K_MSEC(10)); /* Give overflow_thread a chance to run and block */

    /* Now get a message, which should unblock the overflow_thread's put */
    ret = k_msgq_get(&overflow_msgq, rx_msg, K_NO_WAIT);
    zassert_ok(ret, "Failed to get message to unblock put");

    k_sleep(K_MSEC(10)); /* Give overflow_thread a chance to run again and block on get */

    /* Now put a message, which should unblock the overflow_thread's get */
    ret = k_msgq_put(&overflow_msgq, msg_buf, K_NO_WAIT);
    zassert_ok(ret, "Failed to put message to unblock get");

    k_thread_join(&overflow_thread_data, K_FOREVER);
}

/* Test case for message queue empty condition */
static void get_empty_entry(void)
{
    int ret;

    empty_msgq(&kmsgq); /* Ensure it's empty */

    /* Try to get a message from an empty queue */
    ret = k_msgq_get(&kmsgq, msg_buf, K_NO_WAIT);

    zassert_equal(ret, -ENOMSG, "Expected -ENOMSG when getting from an empty message queue, got %d", ret);
}

/* Test case for message queue full condition */
static void put_full_entry(void)
{
    int ret;

    empty_msgq(&kmsgq); /* Ensure it's empty before filling */
    fill_msgq(&kmsgq);  /* Fill the queue to capacity */

    /* Attempt to put one more message into the full queue.
     * This operation should fail immediately because K_NO_WAIT is used
     * and the queue is already at its maximum capacity.
     */
    ret = k_msgq_put(&kmsgq, msg_buf, K_NO_WAIT);

    /* The original assertion was likely 'zassert_not_equal(ret, -ENOMSG, ...)'
     * which failed because 'ret' *was* -ENOMSG.
     * For a test named 'test_msgq_full', the expected behavior is indeed
     * to receive -ENOMSG when attempting to put into a full queue with K_NO_WAIT.
     * Therefore, the assertion logic needs to be inverted to check for equality.
     */

    zassert_equal(ret, -ENOMSG, "Expected -ENOMSG when putting to a full message queue, got %d", ret);
}

/* Test case for message queue reset */
static void test_msgq_reset(void)
{
    struct k_msgq_attrs attrs;

    fill_msgq(&kmsgq);
    k_msgq_get_attrs(&kmsgq, &attrs);
    zassert_equal(attrs.used_msgs, MSGQ_LEN, "Queue not full before reset");

    k_msgq_purge(&kmsgq); /* k_msgq_purge is equivalent to reset for emptying */
    k_msgq_get_attrs(&kmsgq, &attrs);
    zassert_equal(attrs.used_msgs, 0, "Queue not empty after reset");
}


ZTEST_SUITE(msgq_api, NULL, NULL, NULL, NULL, NULL);

ZTEST_UNIT(msgq_api, test_msgq_alloc);
ZTEST_UNIT(msgq_api, test_msgq_attrs_get);
ZTEST_UNIT(msgq_api, test_msgq_isr);
ZTEST_UNIT(msgq_api, test_msgq_thread_overflow);
ZTEST_UNIT(msgq_api, get_empty_entry);
ZTEST_UNIT(msgq_api, put_full_entry);
ZTEST_UNIT(msgq_api, test_msgq_reset);
